using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Windows.Forms;
using System.Drawing;

namespace CursorStudio {
public sealed class ImportSession:IDisposable {
 public string Root,Temp,SuggestedName;
 static bool CursorFile(string p){string e=Path.GetExtension(p).ToLowerInvariant();return e==".cur"||e==".ani";}
 public static Theme Current(string name){return Capture(name,Native.DesktopSize(),Native.CurrentPaths());}
 public static Theme Capture(string name,int pixels,Dictionary<string,string> current){var map=new Dictionary<string,string>();foreach(string role in Native.Roles){string path;if(!current.TryGetValue(role,out path)||String.IsNullOrWhiteSpace(path))path=Native.DefaultPath(role);if(!String.IsNullOrEmpty(path)&&!File.Exists(path))throw new Exception("当前指针文件已不存在，无法导入："+path);map[role]=String.IsNullOrEmpty(path)?null:path;}return Commit(name,pixels,map);}
 public static ImportSession Folder(string path){return new ImportSession{Root=Path.GetFullPath(path),SuggestedName=new DirectoryInfo(path).Name};}
 public static ImportSession Zip(string path){var session=new ImportSession();session.SuggestedName=Path.GetFileNameWithoutExtension(path);session.Temp=Path.Combine(Path.GetTempPath(),"CursorStudio-"+Guid.NewGuid().ToString("N"));session.Root=session.Temp;Directory.CreateDirectory(session.Temp);try{using(var z=ZipFile.OpenRead(path)){long total=0;int files=0;foreach(var e in z.Entries){string name=e.FullName.Replace('/',Path.DirectorySeparatorChar);string dest=Path.GetFullPath(Path.Combine(session.Temp,name));if(!dest.StartsWith(session.Temp+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("压缩包含越界路径，已停止导入。");if(!CursorFile(dest))continue;if(++files>4096||e.Length>64000000||(total+=e.Length)>512000000)throw new Exception("主题包过大，请拆分后导入。");Directory.CreateDirectory(Path.GetDirectoryName(dest));e.ExtractToFile(dest,true);}}return session;}catch{session.Dispose();throw;}}
 public List<string> Groups(){var files=Files(Root);if(files.Length>4096)throw new Exception("主题目录超过 4096 个指针文件，请选择更具体的主题文件夹后导入。");return files.Select(Path.GetDirectoryName).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x).ToList();}
 public static string[] DirectFiles(string dir){return Directory.GetFiles(dir).Where(CursorFile).Take(4097).ToArray();}
 public static string[] Files(string dir){return Walk(dir).Where(CursorFile).Take(4097).ToArray();}
 static IEnumerable<string> Walk(string dir){foreach(string file in Directory.GetFiles(dir))yield return file;foreach(string sub in Directory.GetDirectories(dir)){if((File.GetAttributes(sub)&FileAttributes.ReparsePoint)!=0)continue;foreach(string file in Walk(sub))yield return file;}}
 public void Dispose(){if(Temp!=null&&Directory.Exists(Temp))try{Directory.Delete(Temp,true);}catch{}}
 public static string Guess(string role,string[] files){int idx=Array.IndexOf(Native.Roles,role);string label=Native.Labels[idx];string[][] aliases={new[]{"normal","arrow","正常","标准","default"},new[]{"help","帮助"},new[]{"appstarting","working","background","后台","后台运行"},new[]{"wait","busy","忙碌","忙"},new[]{"crosshair","precision","精确","cross"},new[]{"ibeam","text","文本"},new[]{"nwpen","handwriting","手写","pen"},new[]{"unavailable","disabled","不可用","no"},new[]{"sizens","vertical","垂直","ns"},new[]{"sizewe","horizontal","水平","ew"},new[]{"sizenwse","nwse","沿对角线调整大小1","对角线1"},new[]{"sizenesw","nesw","沿对角线调整大小2","对角线2"},new[]{"sizeall","move","移动"},new[]{"uparrow","alternate","候选","替代"},new[]{"hand","link","链接","链接选择"},new[]{"pin","location","位置"},new[]{"person","个人","人员"}};
 // Common cursor-pack names, including the traditional Windows scheme abbreviations.
 string[][] extra={new[]{"pointer","normal select"},new[]{"help select","helpsel"},new[]{"working in background"},new string[0],new[]{"precision select"},new[]{"beam","text select"},new string[0],new[]{"unavail"},new[]{"vert","vertical resize"},new[]{"horz","horizontal resize"},new[]{"dgn1","diagonal resize 1"},new[]{"dgn2","diagonal resize 2"},new string[0],new[]{"alternate select","up"},new[]{"link select"},new[]{"location select"},new[]{"person select"}};
 return files.Select(f=>new{File=f,Score=GuessScore(Path.GetFileNameWithoutExtension(f),role,label,aliases[idx].Concat(extra[idx]))}).Where(f=>f.Score>0).OrderByDescending(f=>f.Score).ThenByDescending(f=>Path.GetExtension(f.File).Equals(".ani",StringComparison.OrdinalIgnoreCase)).ThenBy(f=>f.File,StringComparer.OrdinalIgnoreCase).ThenBy(f=>f.File,StringComparer.Ordinal).Select(f=>f.File).FirstOrDefault();}
 static string NormalizeName(string name){return System.Text.RegularExpressions.Regex.Replace(name.ToLowerInvariant(),@"[\s_.-]+"," ").Trim();}
 static int NameMatch(string name,string alias){alias=NormalizeName(alias);return name==alias?2:name.EndsWith(" "+alias,StringComparison.Ordinal)?1:0;}
 static int GuessScore(string name,string role,string label,IEnumerable<string> aliases){name=NormalizeName(name);int canonical=NameMatch(name,role),localized=NameMatch(name,label),alias=aliases.Max(a=>NameMatch(name,a));return Math.Max(canonical==2?400:canonical==1?140:0,Math.Max(localized==2?300:localized==1?130:0,alias==2?200:alias==1?120:0));}
 public static Theme Commit(string name,int pixels,Dictionary<string,string> map){if(String.IsNullOrWhiteSpace(name))throw new Exception("请输入主题名称。");if(!map.Values.Any(v=>!String.IsNullOrEmpty(v)))throw new Exception("至少需要指定一个角色。");foreach(var p in map)if(!String.IsNullOrEmpty(p.Value)&&!Native.Valid(p.Value))throw new Exception("Windows 无法加载："+p.Value);var t=new Theme{Name=name.Trim(),Pixels=Native.Snap(pixels)};string dir=Path.Combine(Store.Library,t.Id);Directory.CreateDirectory(dir);try{foreach(var p in map){if(String.IsNullOrEmpty(p.Value))continue;string leaf=p.Key+Path.GetExtension(p.Value).ToLowerInvariant();File.Copy(p.Value,Path.Combine(dir,leaf));t.Files[p.Key]=leaf;}return t;}catch{Directory.Delete(dir,true);throw;}}
}
public sealed class MappingDialog:Form {
 readonly TextBox name;readonly ComboBox[] boxes=new ComboBox[17];readonly string[] paths;public Theme Result;
 public MappingDialog(string dir,string suggestedName=null){Text="核对整套指针 · 导入后复制到主题库";Width=740;Height=670;MinimumSize=new Size(640,550);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);paths=ImportSession.DirectFiles(dir);if(paths.Length>4096)throw new Exception("文件太多，请选择更具体的主题文件夹。");var top=new Panel{Size=new Size(ClientSize.Width,84),Dock=DockStyle.Top,Height=84};top.Controls.Add(new Label{Text="主题名称",Location=new Point(20,18),AutoSize=true});name=new TextBox{Text=suggestedName??new DirectoryInfo(dir).Name,Location=new Point(112,15),Width=ClientSize.Width-132,Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top};top.Controls.Add(name);top.Controls.Add(new Label{Text="按文件名自动匹配，请核对；同角色多个文件可手动选择，缺项使用 Windows 默认。",Location=new Point(20,52),AutoSize=true});Controls.Add(top);var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};Controls.Add(scroll);scroll.BringToFront();for(int i=0;i<17;i++){scroll.Controls.Add(new Label{Text=Native.Labels[i],Location=new Point(20,12+i*37),Width=165,Height=28});var cb=new FluentComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(190,9+i*37),Width=480,Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};cb.Items.Add("— 使用 Windows 默认 —");foreach(string p in paths)cb.Items.Add(p.Substring(dir.Length).TrimStart(Path.DirectorySeparatorChar));string guessed=ImportSession.Guess(Native.Roles[i],paths);cb.SelectedIndex=guessed==null?0:Array.IndexOf(paths,guessed)+1;boxes[i]=cb;scroll.Controls.Add(cb);}var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12)};var ok=new FluentButton{Text="确认导入",Width=110,Height=32};var cancel=new FluentButton{Text="取消",Width=90,Height=32,DialogResult=DialogResult.Cancel};bottom.Controls.Add(ok);bottom.Controls.Add(cancel);Controls.Add(bottom);AcceptButton=ok;CancelButton=cancel;ok.Click+=delegate{try{var map=new Dictionary<string,string>();for(int i=0;i<17;i++)map[Native.Roles[i]]=boxes[i].SelectedIndex==0?null:paths[boxes[i].SelectedIndex-1];Result=ImportSession.Commit(name.Text,Native.DesktopSize(),map);DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(e.Message,"导入失败");}};Skin.Apply(this);}
}
public sealed class ChoiceDialog:Form {
 public string Selected;public ChoiceDialog(List<string> choices,string root){Text="选择要导入的主题";Size=new Size(720,420);StartPosition=FormStartPosition.CenterParent;var list=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};foreach(string p in choices)list.Items.Add(p==root?"根目录":p.Substring(root.Length).TrimStart(Path.DirectorySeparatorChar));list.SelectedIndex=0;Controls.Add(list);var ok=new FluentButton{Text="核对这套主题",Dock=DockStyle.Bottom,Height=44};Controls.Add(ok);ok.Click+=delegate{if(list.SelectedIndex>=0){Selected=choices[list.SelectedIndex];DialogResult=DialogResult.OK;}};list.DoubleClick+=delegate{ok.PerformClick();};Skin.Apply(this);}
}
}
